const raw = $input.first().json.stdout || $input.first().json.output || '';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch(e) {
  // Try extracting JSON from mixed output
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
  else return [{ json: { error: 'Could not parse scraper output', raw } }];
}
const assignments = parsed.assignments || [];
if (assignments.length === 0) {
  return [{ json: { message: 'No upcoming assignments found', count: 0, assignments: [] } }];
}
return assignments.map(a => ({ json: a }));

