=Analyze this Monash University assignment and return JSON:

Title: {{ $json.title }}
Unit/Course: {{ $json.course }}
Due Date: {{ $json.dueDate }}
Description:
{{ $json.description }}

Submission Type: {{ $json.submissionType }}
Files available: {{ ($json.files || []).map(f => f.name).join(', ') || 'none' }}

Return ONLY valid JSON as described in your system prompt.

parameters.jsCode:
const fs = require('fs');
const path = require('path');
const workdir = $fromAI('workdir', 'Workspace directory path', 'string');
const briefPath = path.join(workdir, 'ASSIGNMENT_BRIEF.txt');
if (fs.existsSync(briefPath)) {
  return fs.readFileSync(briefPath, 'utf8');
}
return 'Brief not found at: ' + briefPath;

const output = $input.first().json.output || $input.first().json.text || '';
let analysis;
try {
  // Extract JSON from agent output
  const match = output.match(/\{[\s\S]*\}/);
  analysis = match ? JSON.parse(match[0]) : {};
} catch(e) {
  analysis = { type: 'both', language: 'python', hasLatexReport: true, hasMathematics: false };
}
// Merge with original assignment data
const original = $('Build Analyzer Prompt').first().json;
return [{
  json: {
    ...original,
    analysis,
    taskType:  analysis.type || 'both',
    language:  analysis.language || 'python',
    needsCode:   ['code', 'both', 'math'].includes(analysis.type),
    needsReport: ['report', 'both'].includes(analysis.type),
    needsMath:   analysis.hasMathematics || analysis.type === 'math',
  }
}];

parameters.text:
=Complete this {{ $json.language || 'programming' }} assignment.

Assignment: {{ $json.title }}
Unit: {{ $json.unitCode }}
Due: {{ $json.dueDate }}
Workspace: {{ $json.workspaceDir }}

Key requirements:
{{ ($json.analysis?.keyRequirements || []).join('\n') }}

Testing notes: {{ $json.analysis?.testingNotes || 'Write comprehensive tests' }}

Components to complete:
{{ ($json.analysis?.components || []).join('\n') }}

Start by reading all files in the workspace, then write the solution code, write tests, run them in Docker, and fix until all pass.

parameters.jsCode:
const fs   = require('fs');
const path = require('path');
const fse  = require('fs-extra');
const filePath = $fromAI('file_path', 'Absolute path to write', 'string');
const content  = $fromAI('content',   'File content to write',  'string');
fse.mkdirpSync(path.dirname(filePath));
fs.writeFileSync(filePath, content, 'utf8');
return JSON.stringify({ success: true, path: filePath, bytes: content.length });

const fs   = require('fs');
const filePath = $fromAI('file_path', 'Absolute path to read', 'string');
if (!fs.existsSync(filePath)) return JSON.stringify({ error: 'File not found: ' + filePath });
const content = fs.readFileSync(filePath, 'utf8');
return JSON.stringify({ content, path: filePath, bytes: content.length });

const fs   = require('fs');
const path = require('path');
const dirPath = $fromAI('dir_path', 'Directory path to list', 'string');
if (!fs.existsSync(dirPath)) return JSON.stringify({ error: 'Directory not found: ' + dirPath });
const entries = fs.readdirSync(dirPath, { withFileTypes: true });
return JSON.stringify({
  path: dirPath,
  entries: entries.map(e => ({
    name:  e.name,
    type:  e.isDirectory() ? 'dir' : 'file',
    size:  e.isFile() ? fs.statSync(path.join(dirPath, e.name)).size : null
  }))
});

const { spawnSync } = require('child_process');
const command   = $fromAI('command',  'Shell command to execute',                 'string');
const workdir   = $fromAI('workdir',  'Working directory inside container',        'string');
const container = process.env.DOCKER_CONTAINER_NAME || 'assignment-runner';
const result = spawnSync('docker', [
  'exec', '-w', workdir, container, 'bash', '-c', command
], { timeout: 120000, encoding: 'utf8' });
return JSON.stringify({
  stdout:   result.stdout   || '',
  stderr:   result.stderr   || '',
  exitCode: result.status   ?? 1,
  success:  result.status === 0,
  command, workdir
});

const { spawnSync } = require('child_process');
const expression = $fromAI('expression', 'Math expression to evaluate', 'string');
const mcpUrl     = process.env.MATHEMATICA_MCP_URL || '';
// Try MCP first
if (mcpUrl) {
  try {
    const resp = await fetch(`${mcpUrl}/evaluate`, {
      method: 'POST', headers: {'Content-Type':'application/json'},
      body: JSON.stringify({ expression }),
      signal: AbortSignal.timeout(15000)
    });
    if (resp.ok) {
      const data = await resp.json();
      return JSON.stringify({ result: data.result, engine: 'mathematica', expression });
    }
  } catch {}
}
// SymPy fallback
const pyCode = `from sympy import *\nx,y,z,n,t=symbols('x y z n t')\ntry:\n    r=eval(${JSON.stringify(expression)})\n    print(repr(r))\nexcept:\n    r=sympify(${JSON.stringify(expression)})\n    print(repr(r))`;
const r = spawnSync('docker',['exec','assignment-runner','python3','-c',pyCode],{timeout:15000,encoding:'utf8'});
return JSON.stringify({ result: r.stdout.trim() || r.stderr.trim(), engine: 'sympy', expression });

