const fs   = require('fs');
const path = require('path');
const fse  = require('fs-extra');
const texPath = $fromAI('tex_path', 'Absolute path for .tex file', 'string');
const content = $fromAI('content',  'LaTeX source content',         'string');
fse.mkdirpSync(path.dirname(texPath));
fs.writeFileSync(texPath, content, 'utf8');
return JSON.stringify({ success: true, path: texPath, bytes: content.length });

const { spawnSync } = require('child_process');
const texPath   = $fromAI('tex_path', 'Absolute path to .tex file', 'string');
const path      = require('path');
const texDir    = path.dirname(texPath);
const texFile   = path.basename(texPath);
// Convert host path to container path (assumes /workspace is shared)
const containerDir = texDir.replace(/.*workspace/, '/workspace');
const result = spawnSync('docker', [
  'exec', '-w', containerDir, 'assignment-runner',
  'pdflatex', '-interaction=nonstopmode', '-halt-on-error', texFile
], { timeout: 120000, encoding: 'utf8' });
// Run twice for cross-references
if (result.status === 0) {
  spawnSync('docker', ['exec', '-w', containerDir, 'assignment-runner',
    'pdflatex', '-interaction=nonstopmode', texFile], { timeout: 60000, encoding: 'utf8' });
}
return JSON.stringify({
  success:  result.status === 0,
  stdout:   result.stdout?.slice(-3000) || '',
  stderr:   result.stderr?.slice(-1000) || '',
  pdfPath:  texPath.replace('.tex', '.pdf')
});

const fs       = require('fs');
const filePath = $fromAI('file_path', 'Absolute path to file', 'string');
if (!fs.existsSync(filePath)) return JSON.stringify({ error: 'Not found: ' + filePath });
const content  = fs.readFileSync(filePath, 'utf8');
return JSON.stringify({ content: content.slice(0, 50000), path: filePath });

const { spawnSync } = require('child_process');
const expression = $fromAI('expression', 'Math expression to evaluate', 'string');
const pyCode = `from sympy import *
x,y,z,n,t=symbols('x y z n t')
try:
    e=sympify(${JSON.stringify(expression)})
    print(repr(e), '|||', latex(e))
except Exception as err:
    print(f'ERROR:{err}', '|||', '')`;
const r = spawnSync('docker',['exec','assignment-runner','python3','-c',pyCode],{timeout:15000,encoding:'utf8'});
const [result, latexStr] = r.stdout.trim().split('|||');
return JSON.stringify({ result: result?.trim(), latex: latexStr?.trim(), expression });

const fs      = require('fs');
const path    = require('path');
const dirPath = $fromAI('dir_path', 'Directory to list', 'string');
if (!fs.existsSync(dirPath)) return JSON.stringify({ error: 'Not found: ' + dirPath });
const entries = fs.readdirSync(dirPath, { withFileTypes: true });
return JSON.stringify({ path: dirPath, entries: entries.map(e => ({ name: e.name, type: e.isDirectory()?'dir':'file' })) });

const items = $input.all();
const results = [];
for (const item of items) {
  const raw = item.json.stdout || item.json.output || '{}';
  let pkg = {};
  try { const m = raw.match(/\{[\s\S]*\}/); if (m) pkg = JSON.parse(m[0]); } catch {}
  results.push({
    assignment:       item.json.title || 'Unknown',
    unit:             item.json.unitCode || 'Unknown',
    dueDate:          item.json.dueDate || 'Unknown',
    outputFolder:     pkg.outputDir || 'See workspace',
    submissionFiles:  pkg.submissionFiles || [],
    readyToSubmit:    pkg.readyForSubmission || false,
    packagedAt:       pkg.packagedAt || new Date().toISOString(),
  });
}
const readyCount = results.filter(r => r.readyToSubmit).length;
console.log('\n' + '='.repeat(60));
console.log('MONASH ASSIGNMENT PIPELINE — RESULTS');
console.log('='.repeat(60));
for (const r of results) {
  const icon = r.readyToSubmit ? '✓ READY' : '⚠ INCOMPLETE';
  console.log(`\n[${icon}] ${r.unit}: ${r.assignment}`);
  console.log(`  Due: ${r.dueDate}`);
  console.log(`  Folder: ${r.outputFolder}`);
  if (r.submissionFiles.length) console.log(`  Files: ${r.submissionFiles.join(', ')}`);
}
console.log(`\n${readyCount}/${results.length} assignments ready for submission.`);
console.log('='.repeat(60) + '\n');
return [{ json: { results, readyCount, total: results.length } }];
